def is_prime(n):
    if n is None or not isinstance(n, int):
        return False
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def solve():
    possible_values = [-3, -2, -1, 1, 2, 3]
    good_triples = []

    for x in possible_values:
        for y in possible_values:
            for z in possible_values:
                try:
                    # Calculate P = y^x * z^y * x^z
                    # We use standard Python exponentiation which handles integer exponents
                    # even with negative bases, resulting in integers or floats.

                    # Since we require P to be a positive prime, P must be an integer.

                    p_yx = y**x
                    p_zy = z**y
                    p_xz = x**z

                    # Check if intermediate results are integers (or nearly so, for float precision safety)
                    if not (isinstance(p_yx, int) and isinstance(p_zy, int) and isinstance(p_xz, int)):
                        continue

                    P = p_yx * p_zy * p_xz

                    # Check if P is a positive prime number
                    if is_prime(P):
                        S = x**2 + y**2 + z**2
                        good_triples.append((S, x, y, z))

                except OverflowError:
                    # Skip if the number is too large to handle standard integer types
                    continue
                except ValueError:
                    # Should not happen with integer bases and integer exponents, but safe to catch
                    continue

    # Sort by S (the first element of the tuple)
    good_triples.sort()

    # Format the output: (x, y, z) triples sorted by S
    results = []
    for S, x, y, z in good_triples:
        results.append(f"S = {S}: ({x}, {y}, {z})")

    return "\\n".join(results)

